.js .h3d-hero.pin .h3d-stage { position: sticky; top: var(--hd); height: calc(100vh - var(--hd)); height: calc(100svh - var(--hd)); }
.h3d-field { position: absolute; inset: 0; width: 100%; height: 100%; z-index: -1; pointer-events: none; }
.h3d-stage-in { max-width: var(--wrap); margin: 0 auto; padding: clamp(1.5rem, 4vh, 3rem) 1.25rem; height: 100%; display: grid; gap: 1rem; align-content: center; align-items: center; }
@media (min-width: 900px) { .h3d-stage-in { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 2.5rem; } }
.h3d-copy { min-width: 0; }
.h3d-hero h1 { margin: 0; max-width: none; color: #fff; font: 500 clamp(1.3rem, 3vw, 2.4rem)/1.18 var(--display); letter-spacing: -.015em; }
.h3d-hero h1 .t { display: block; position: relative; padding: .28em 0 .28em 1.5em; color: #fff; text-decoration: none; transition: color 1.2s ease, transform 1.2s cubic-bezier(.2,.7,.2,1); text-wrap: balance; }
.h3d-hero h1 .t::before { content: ""; position: absolute; left: .2em; top: .78em; width: .55em; height: .55em; border-radius: 50%; border: 2px solid #C08A1E; background: #000; transition: background-color 1.2s ease, box-shadow 1.2s ease; }
.h3d-hero h1 .t::after { content: ""; position: absolute; left: calc(.475em - 1px); top: 1.33em; bottom: -.76em; width: 2px; background: rgba(168,112,0,.45); }
.h3d-hero h1 .t:last-child::after { display: none; }
.h3d-hero.pin h1 .t { color: var(--dim); }
