.h3d-plane i:nth-of-type(1) { left: -5px; top: -5px; } .h3d-plane i:nth-of-type(2) { right: -5px; top: -5px; }
.h3d-plane i:nth-of-type(3) { left: -5px; bottom: -5px; } .h3d-plane i:nth-of-type(4) { right: -5px; bottom: -5px; }
.h3d-layer-list { list-style: none; margin: 1.8rem 0 0; padding: 0; display: grid; gap: .5rem; }
.h3d-layer-list a { display: grid; grid-template-columns: auto 1fr; gap: .2rem 1rem; padding: .9rem 1rem; border-radius: 6px; border: 1px solid rgba(255,255,255,.12); color: #fff; text-decoration: none; transition: border-color .4s, background-color .4s; }
.h3d-layer-list a:hover, .h3d-layer-list a:focus-visible, .h3d-layer-list a.lit { border-color: #C08A1E; background: rgba(192,138,30,.08); }
.h3d-layer-list b { grid-row: span 2; font: 500 1.6rem/1 var(--display); color: #C08A1E; align-self: center; }
.h3d-layer-list strong { font: 600 1.1rem var(--body); }
.h3d-layer-list small { color: #B9C3D1; font-size: .98rem; }

/* 3. anel de serviços (sem JavaScript, vira uma grade comum) */
.h3d-ring-wrap { margin-top: 2.5rem; }
.h3d-ring { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 1rem; }
.h3d-tile { display: flex; flex-direction: column; justify-content: space-between; gap: 1.2rem; height: 100%; min-height: 230px; padding: 1.3rem; border-radius: 10px; text-decoration: none; background: #fff; color: var(--ink); border: 1px solid var(--line); transition: border-color .4s, box-shadow .4s; }
.h3d-tile:hover, .h3d-tile:focus-visible { border-color: var(--gold); box-shadow: 0 16px 40px rgba(22,35,58,.16); }
.h3d-tile svg { width: 46px; height: 46px; }
.h3d-tile strong { display: block; font: 500 1.08rem/1.25 var(--display); }
.h3d-tile small { display: block; margin-top: .45rem; color: var(--slate); font-size: .95rem; line-height: 1.35; }
.h3d-ring-ctrl { display: none; }
.h3d-ring-wrap.on { position: relative; height: clamp(320px, 38vw, 400px); perspective: 900px; touch-action: pan-y; cursor: grab; }
.h3d-ring-wrap.on .h3d-ring { display: block; position: absolute; left: 50%; top: 50%; width: 0; height: 0; transform-style: preserve-3d; }
.h3d-ring-wrap.on .h3d-ring > li { position: absolute; width: 230px; height: 250px; left: -115px; top: -125px; backface-visibility: hidden; }
.h3d-ring-wrap.on + .h3d-ring-ctrl { display: flex; justify-content: center; gap: .75rem; margin-top: 1.5rem; }
.h3d-ring-ctrl button { min-width: 48px; min-height: 48px; border-radius: 50%; border: 1.5px solid var(--ink); background: transparent; color: var(--ink); font: 600 1.2rem var(--body); cursor: pointer; }
.h3d-ring-ctrl button:hover { background: var(--ink); color: #fff; }
@media (max-width: 599px) { .h3d-ring-wrap.on .h3d-ring > li { width: 190px; height: 230px; left: -95px; top: -115px; } }

/* 4. produtos em aparelhos */
.h3d-prods { display: grid; gap: 3rem; margin-top: 2.5rem; }
@media (min-width: 900px) { .h3d-prods { grid-template-columns: 7fr 5fr; align-items: end; } }
.h3d-prod { display: grid; gap: 1.2rem; }
.h3d-prod h3 { margin: 0; color: #fff; font: 500 1.4rem var(--display); }
.h3d-prod ul { margin: 0; padding: 0; list-style: none; display: flex; flex-wrap: wrap; gap: .5rem; }
.h3d-prod li { padding: .45rem .8rem; border: 1px solid rgba(255,255,255,.18); border-radius: 999px; font-size: .95rem; color: #B9C3D1; }
.h3d-prod a.more { color: #C08A1E; font-weight: 600; justify-self: start; }
.h3d-scene { perspective: 1200px; height: clamp(250px, 30vw, 340px); display: grid; place-items: center; }
.h3d-laptop { width: min(100%, 520px); transform-style: preserve-3d; transform: rotateX(16deg) rotateY(-22deg); transition: transform 1.2s cubic-bezier(.2,.7,.2,1); }
.h3d-laptop .scr { aspect-ratio: 16/10; border-radius: 12px 12px 0 0; border: 10px solid #1C2433; border-bottom-width: 14px; background: #0B1220; padding: 10px; display: grid; grid-template-columns: 60px 1fr; gap: 8px; }
.h3d-laptop .base { height: 16px; margin: 0 -6%; border-radius: 0 0 14px 14px; background: #1F2836; transform: rotateX(70deg); transform-origin: top; }
.h3d-cal-side { display: grid; gap: 6px; align-content: start; }
.h3d-cal-side i { height: 8px; border-radius: 3px; background: rgba(143,163,191,.35); }
.h3d-cal-side i:first-child { background: #C08A1E; }
.h3d-cal { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.h3d-cal i { border-radius: 4px; background: rgba(143,163,191,.12); min-height: 22px; }
.h3d-cal i.a { background: rgba(192,138,30,.75); } .h3d-cal i.b { background: rgba(143,163,191,.55); } .h3d-cal i.c { background: rgba(192,138,30,.35); }
.h3d-phone { width: 180px; aspect-ratio: 9/18.5; border-radius: 28px; border: 9px solid #1C2433; background: #0B1220; padding: 16px 10px; display: flex; flex-direction: column; gap: 8px; justify-content: flex-end; transform: rotateY(24deg) rotateX(10deg); transform-style: preserve-3d; transition: transform 1.2s cubic-bezier(.2,.7,.2,1); }
.h3d-bubble { max-width: 82%; padding: 6px 9px; border-radius: 12px; font-size: .72rem; line-height: 1.3; }
.h3d-bubble.in { background: rgba(143,163,191,.22); color: #fff; align-self: flex-start; border-bottom-left-radius: 3px; }
.h3d-bubble.out { background: #C08A1E; color: #000; align-self: flex-end; border-bottom-right-radius: 3px; }

/* 5. escada de sete etapas */
.h3d-steps-scene { perspective: 1400px; margin-top: 3rem; }
.h3d-steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 10px; align-items: end; transform: rotateX(28deg); transform-origin: bottom; }
.h3d-steps li { border-radius: 8px 8px 0 0; background: #fff; border: 1px solid var(--line); padding: .9rem .7rem; display: flex; flex-direction: column; gap: .4rem; transform-origin: bottom; transition: transform 1s cubic-bezier(.2,.7,.2,1); box-shadow: 0 -6px 0 0 var(--gold) inset; }
.h3d-steps b { font: 500 1.6rem/1 var(--display); color: var(--gold-text); }
.h3d-steps strong { font: 600 1rem/1.25 var(--body); color: var(--ink); }
.h3d-steps small { color: var(--slate); font-size: .88rem; line-height: 1.3; }
.h3d-steps li:nth-child(1){height:140px}.h3d-steps li:nth-child(2){height:165px}.h3d-steps li:nth-child(3){height:190px}.h3d-steps li:nth-child(4){height:215px}.h3d-steps li:nth-child(5){height:240px}.h3d-steps li:nth-child(6){height:265px}.h3d-steps li:nth-child(7){height:290px}
.h3d-steps.wait li { transform: scaleY(.15); }
.h3d-steps.in li:nth-child(2){transition-delay:.12s}.h3d-steps.in li:nth-child(3){transition-delay:.24s}.h3d-steps.in li:nth-child(4){transition-delay:.36s}.h3d-steps.in li:nth-child(5){transition-delay:.48s}.h3d-steps.in li:nth-child(6){transition-delay:.6s}.h3d-steps.in li:nth-child(7){transition-delay:.72s}
.h3d-more { display: inline-block; margin-top: 1.6rem; font-weight: 600; }
@media (max-width: 899px) {
  .h3d-steps { grid-template-columns: 1fr; transform: none; gap: 8px; }
  .h3d-steps li { height: auto !important; border-radius: 8px; box-shadow: 6px 0 0 0 var(--gold) inset; padding: .9rem 1rem .9rem 1.4rem; display: grid; grid-template-columns: auto 1fr; gap: .1rem 1rem; }
  .h3d-steps b { grid-row: span 2; align-self: center; }
  .h3d-steps.wait li { transform: translateX(-12px); transition: transform .8s; }
}
.h3d-steps.in li { transform: none; opacity: 1; }

/* 6. fundadora */
.h3d-founder { display: grid; gap: 2.5rem; align-items: center; }
@media (min-width: 900px) { .h3d-founder { grid-template-columns: 5fr 7fr; gap: 4rem; } }
.h3d-pscene { perspective: 1000px; display: grid; place-items: center; }
.h3d-portrait { position: relative; width: min(100%, 360px); transform-style: preserve-3d; transform: rotateY(-10deg) rotateX(4deg); transition: transform .9s cubic-bezier(.2,.7,.2,1); }
.h3d-pnet { position: absolute; inset: -18% -24%; width: 148%; height: 136%; transform: translateZ(-80px); }
.h3d-portrait img { position: relative; display: block; width: 100%; height: auto; border-radius: 10px; border: 1px solid var(--line); transform: translateZ(30px); box-shadow: 0 30px 60px rgba(22,35,58,.18); }
.h3d-marks { list-style: none; margin: 1.8rem 0 0; padding: 0; border-left: 2px solid var(--gold); }
.h3d-marks li { position: relative; padding: .7rem 0 .7rem 1.5rem; display: grid; grid-template-columns: 4.6rem 1fr; gap: 1rem; align-items: baseline; }
.h3d-marks li::before { content: ""; position: absolute; left: -7px; top: 1.05rem; width: 12px; height: 12px; border-radius: 50%; background: #fff; border: 2px solid var(--gold); }
.h3d-marks b { font: 500 1.05rem var(--display); color: var(--gold-text); font-variant-numeric: tabular-nums; }
.h3d-marks span { color: var(--ink); font-weight: 500; }

/* 8. final */
.h3d-final-in { display: grid; gap: 2rem; align-items: center; }
@media (min-width: 900px) { .h3d-final-in { grid-template-columns: 7fr 5fr; } }
.h3d-final canvas { width: 100%; max-width: 320px; aspect-ratio: 1; justify-self: center; display: block; }
.h3d-final .btn { margin-top: 1.8rem; }

@media (prefers-reduced-motion: reduce) {
  .h3d-hero h1 .t, .h3d-stack-rot, .h3d-plane, .h3d-laptop, .h3d-phone, .h3d-portrait, .h3d-steps li { transition: none !important; }
}

/* o celular tem 370 px de altura: a cena precisa de espaço para ele não cobrir o título abaixo */
.h3d-scene:has(> .h3d-phone) { height: 430px; }
