.k3-one { margin: 1rem 0 0; font-size: clamp(1.1rem, 1.8vw, 1.28rem); line-height: 1.5; max-width: 52ch; color: var(--slate); }
.k3-black .k3-one { color: var(--t2); }
.k3 .btn.gold { background: var(--g); border-color: var(--g); color: #000; font-weight: 700; font-size: 1.1rem; min-height: 52px; }
.k3 .btn.gold:hover { background: #D69C2A; border-color: #D69C2A; }
.k3 .btn.line { background: transparent; border-color: rgba(255,255,255,.55); color: #fff; }
.k3 .btn.line:hover { border-color: #fff; background: transparent; }
.k3-black :focus-visible { outline-color: var(--g); }

/* abertura */
.k3-hero { position: relative; background: #000; color: #fff; overflow: hidden; isolation: isolate; }
.k3-hero-in { max-width: var(--wrap); margin: 0 auto; padding: clamp(2rem, 6vw, 4.5rem) 1.25rem clamp(2.5rem, 6vw, 4.5rem); display: grid; gap: 1.5rem; align-items: center; }
@media (min-width: 900px) { .k3-hero-in { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 3rem; min-height: min(78vh, 640px); } }
.k3-hero .crumb { color: var(--t2); margin: 0 0 1.2rem; }
.k3-hero .crumb a { color: #fff; }
.k3-hero h1 { margin: 0; max-width: 18ch; color: #fff; font: 500 clamp(1.9rem, 4.6vw, 3.3rem)/1.1 var(--display); letter-spacing: -.02em; }
.k3-lead { margin: 1.3rem 0 0; max-width: 46ch; color: var(--t2); font-size: clamp(1.1rem, 1.8vw, 1.28rem); line-height: 1.55; }
.k3-btns { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 1.8rem; }
.k3-obj { position: relative; min-width: 0; aspect-ratio: 1; width: min(100%, 460px); justify-self: center; }
.k3-obj canvas { width: 100%; height: 100%; display: block; }
@media (max-width: 899px) { .k3-obj { order: -1; width: min(70vw, 280px); margin-bottom: -.5rem; } }

/* o que entregamos: ficha técnica em duas colunas */
.k3-spec { list-style: none; margin: 2.2rem 0 0; padding: 0; display: grid; gap: 0 3rem; border-top: 1px solid var(--line); }
@media (min-width: 760px) { .k3-spec { grid-template-columns: 1fr 1fr; } }
.k3-spec li { display: grid; grid-template-columns: 44px 1fr; gap: .1rem 1rem; padding: 1.15rem 0; border-bottom: 1px solid var(--line); align-items: start; }
.k3-spec svg { grid-row: span 2; width: 44px; height: 44px; }
.k3-spec strong { font: 600 1.1rem/1.3 var(--body); color: var(--ink); }
.k3-spec span { color: var(--slate); font-size: 1rem; line-height: 1.45; }
.k3-spec a { color: var(--gold-text); }

/* camadas explodidas em 3D (anatomia) */
.k3-anat { display: grid; gap: 2.5rem; align-items: center; margin-top: 1rem; }
@media (min-width: 900px) { .k3-anat { grid-template-columns: minmax(0, 6fr) minmax(0, 6fr); gap: 3rem; } }
.k3-stack { position: relative; height: clamp(340px, 44vw, 480px); perspective: 1200px; }
.k3-stack-rot { position: absolute; inset: 0; transform-style: preserve-3d; transform: rotateX(60deg) rotateZ(-36deg); transition: transform 1.6s cubic-bezier(.2,.7,.2,1); }
.k3-plane { position: absolute; left: 50%; top: 50%; width: min(64%, 320px); aspect-ratio: 1.3; translate: -50% -50%; border-radius: 8px; border: 1.5px solid var(--g); background: rgba(192,138,30,.06); display: grid; place-items: center; transition: transform 1.6s cubic-bezier(.2,.7,.2,1), background-color .5s; }
.k3-plane span { font: 500 clamp(.95rem, 1.8vw, 1.2rem) var(--display); color: #fff; transform: rotateZ(36deg); }
.k3-plane.lit { background: rgba(192,138,30,.24); }
.k3-layers { list-style: none; margin: 0; padding: 0; display: grid; gap: .5rem; counter-reset: l; }
.k3-layers li { display: grid; grid-template-columns: 2.2rem 1fr; gap: .15rem 1rem; padding: .85rem 1rem; border: 1px solid rgba(255,255,255,.14); border-radius: 6px; transition: border-color .4s, background-color .4s; }
.k3-layers li.lit, .k3-layers li:hover { border-color: var(--g); background: rgba(192,138,30,.08); }
.k3-layers b { grid-row: span 2; font: 500 1.4rem/1 var(--display); color: var(--g); align-self: center; }
.k3-layers strong { font: 600 1.06rem var(--body); color: #fff; }
.k3-layers small { color: var(--t2); font-size: .97rem; }

/* pilares/opções com profundidade */
.k3-pillars { display: grid; gap: 1rem; margin-top: 2.2rem; perspective: 1400px; }
@media (min-width: 700px) { .k3-pillars { grid-template-columns: repeat(var(--n, 3), minmax(0, 1fr)); } }
.k3-pillar { position: relative; padding: 1.4rem 1.3rem 1.5rem; border-radius: 10px; background: #fff; border: 1px solid var(--line); transform: rotateX(8deg); transform-origin: bottom; transition: transform .9s cubic-bezier(.2,.7,.2,1), box-shadow .5s; box-shadow: 0 -5px 0 0 var(--gold) inset; }
.k3-pillar:hover { transform: rotateX(0) translateY(-6px); box-shadow: 0 -5px 0 0 var(--gold) inset, 0 18px 36px rgba(22,35,58,.14); }
.k3-pillar h3 { margin: .9rem 0 .5rem; font: 500 1.2rem/1.25 var(--display); color: var(--ink); }
.k3-pillar ul { margin: 0; padding: 0; list-style: none; display: grid; gap: .45rem; }
.k3-pillar li { color: var(--slate); font-size: .98rem; line-height: 1.4; padding-left: 1.1rem; position: relative; }
.k3-pillar li::before { content: ""; position: absolute; left: 0; top: .55em; width: 7px; height: 7px; border-radius: 50%; background: var(--gold); }
.k3-pillar svg { width: 40px; height: 40px; }
.k3-black .k3-pillar { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.14); }
.k3-black .k3-pillar h3 { color: #fff; }
.k3-black .k3-pillar li { color: var(--t2); }

/* fluxo em sequência (etapas reais) */
.k3-flow { list-style: none; margin: 2.4rem 0 0; padding: 0; display: grid; gap: 0; counter-reset: f; }
@media (min-width: 900px) { .k3-flow { grid-template-columns: repeat(var(--n, 5), minmax(0, 1fr)); } }
.k3-flow li { position: relative; padding: 0 1.2rem 1.6rem 3.4rem; }
.k3-flow li::before { counter-increment: f; content: counter(f); position: absolute; left: 0; top: 0; width: 2.4rem; height: 2.4rem; display: grid; place-items: center; border-radius: 50%; border: 2px solid var(--gold); background: var(--mist); font: 500 1rem var(--display); color: var(--ink); z-index: 1; }
.k3-flow li::after { content: ""; position: absolute; left: calc(1.2rem - 1px); top: 2.4rem; bottom: 0; width: 2px; background: var(--gold); opacity: .5; }
.k3-flow li:last-child::after { display: none; }
.k3-flow strong { display: block; font: 600 1.08rem/1.3 var(--body); color: var(--ink); padding-top: .35rem; }
.k3-flow span { display: block; margin-top: .3rem; color: var(--slate); font-size: .98rem; line-height: 1.4; }
@media (min-width: 900px) {
  .k3-flow li { padding: 3.6rem 1rem 0 0; }
  .k3-flow li::after { left: 2.4rem; right: 0; top: calc(1.2rem - 1px); bottom: auto; width: auto; height: 2px; }
}
.k3-white .k3-flow li::before { background: #fff; }
.k3-black .k3-flow li::before { background: #000; color: #fff; border-color: var(--g); }
.k3-black .k3-flow strong { color: #fff; }
.k3-black .k3-flow span { color: var(--t2); }

/* chips de tipos */
.k3-chips { list-style: none; margin: 1.8rem 0 0; padding: 0; display: flex; flex-wrap: wrap; gap: .6rem; }
.k3-chips li { padding: .65rem 1.1rem; border-radius: 999px; border: 1px solid var(--line); background: #fff; color: var(--ink); font-weight: 500; }
.k3-chips li.g { border-color: var(--gold); }

/* produtos próprios */
.k3-own { display: grid; gap: 1rem; margin-top: 2rem; }
@media (min-width: 700px) { .k3-own { grid-template-columns: 1fr 1fr; } }
.k3-own a { display: grid; gap: .3rem; padding: 1.3rem 1.4rem; border-radius: 10px; border: 1px solid rgba(255,255,255,.16); color: #fff; text-decoration: none; transition: border-color .4s, background-color .4s; }
.k3-own a:hover { border-color: var(--g); background: rgba(192,138,30,.08); }
.k3-own b { font: 500 1.25rem var(--display); }
.k3-own span { color: var(--t2); }

/* outros ganchos + fechamento */
.k3-next { list-style: none; margin: 2rem 0 0; padding: 0; display: grid; gap: .6rem; }
@media (min-width: 760px) { .k3-next { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.k3-next a { display: flex; align-items: center; gap: .8rem; min-height: 64px; padding: .8rem 1rem; border: 1px solid rgba(255,255,255,.16); border-radius: 8px; color: #fff; text-decoration: none; font-weight: 600; transition: border-color .4s, background-color .4s; }
.k3-next a:hover { border-color: var(--g); background: rgba(192,138,30,.08); }
.k3-next svg { flex: none; width: 30px; height: 30px; }
.k3-final { display: grid; gap: 1rem; margin-top: 3.5rem; padding-top: 3rem; border-top: 1px solid rgba(255,255,255,.12); }
.k3-final h2 { max-width: 22ch; }

@media (prefers-reduced-motion: reduce) { .k3-stack-rot, .k3-plane, .k3-pillar { transition: none !important; } }
